NOW = datetime(2024, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


def _task(id, title="task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
          due_at=None, tags=None, created_at=None):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at, tags=tags or [],
        created_at=created_at or NOW - timedelta(hours=id),
    )


@pytest.fixture
def sample_tasks():
    return [
        _task(1, "Buy groceries", tags=[Tag("shopping")],
              priority=TaskPriority.LOW),
        _task(2, "Write report", status=TaskStatus.DONE,
              priority=TaskPriority.HIGH),
        _task(3, "Call dentist", due_at=NOW - timedelta(days=1),
              tags=[Tag("health")]),
        _task(4, "Plan vacation", due_at=NOW + timedelta(days=7),
              tags=[Tag("shopping"), Tag("fun")]),
        _task(5, "Read book", priority=TaskPriority.LOW),
    ]


class TestTaskQueryValidation:
    def test_invalid_sort_field(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(sort="invalid")

