        with pytest.raises(TaskQueryError):
            TaskQuery(limit=0)

    def test_invalid_limit_over_100(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(limit=101)

    def test_invalid_offset_negative(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(offset=-1)

