        q = TaskQuery(tag="  Shopping ")
        assert q.tag == "shopping"

    def test_invalid_tag(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_search_whitespace_only_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None


