        page = apply_query(sample_tasks, TaskQuery(offset=100), NOW)
        assert len(page.items) == 0
        assert page.has_more is False

    def test_has_more_exact_boundary(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(limit=5), NOW)
        assert page.has_more is False

